package com.decms.servlet;
import com.decms.util.*;import jakarta.servlet.*;import jakarta.servlet.http.*;import jakarta.servlet.annotation.*;import java.io.*;import java.sql.*;
@WebServlet("/reports") public class ReportServlet extends HttpServlet{
 protected void service(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{if(!Auth.protect(r,s))return;super.service(r,s);}
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try(Connection c=DB.getConnection();Statement st=c.createStatement();ResultSet rs=st.executeQuery("SELECT rp.*,ca.case_no FROM reports rp JOIN cases ca ON ca.id=rp.case_id ORDER BY rp.id DESC")){r.setAttribute("rows",rs);r.getRequestDispatcher("/reports.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String a=r.getParameter("action");try(Connection c=DB.getConnection()){if("delete".equals(a)){PreparedStatement p=c.prepareStatement("DELETE FROM reports WHERE id=?");p.setInt(1,Integer.parseInt(r.getParameter("id")));p.executeUpdate();}else{PreparedStatement p=c.prepareStatement("INSERT INTO reports(case_id,report_title,author,report_text) VALUES(?,?,?,?)");p.setInt(1,Integer.parseInt(r.getParameter("case_id")));p.setString(2,r.getParameter("report_title"));p.setString(3,r.getParameter("author"));p.setString(4,r.getParameter("report_text"));p.executeUpdate();}}catch(Exception e){throw new ServletException(e);}s.sendRedirect(r.getContextPath()+"/reports");}
}
